var KeyPositionPiano={elems:{},minUsedKeyNum:-1,maxUsedKeyNum:-1,numKeys:-1,startNoteKey:-1,noteKeyAr:[],displayType:''};KeyPositionPiano.init=function(){this.elems.piano=$('#piano');this.numKeys=parseInt(this.elems.piano.attr('data-num-keys'));this.startNoteKey=parseInt(this.elems.piano.attr('data-start-note-key'))};KeyPositionPiano.update=function(ar,displayType){this.noteKeyAr=ar;this.displayType=displayType;this.displayKeys();this.setHiddenKeys('mobile');this.setHiddenKeys('tablet')};KeyPositionPiano.displayKeys=function(){var note_class,root_class;this.elems.piano.find('.in_chord').removeClass('in_chord chord_root');if(this.displayType=='scale'){this.elems.piano.find('.in_scale').removeClass('in_scale scale_root');note_class='in_scale';root_class='scale_root'}else{note_class='in_chord';root_class='chord_root'}var maxSpan=14;var minRootKeyNum=Math.floor(this.numKeys/2)-maxSpan;var prevKeyNum=minRootKeyNum;this.minUsedKeyNum=this.maxUsedKeyNum=minRootKeyNum;var x,keyNum,elem;for(x=0;x<this.noteKeyAr.length;x++){keyNum=(Note.allNoteCount+this.noteKeyAr[x]-this.startNoteKey)%Note.allNoteCount;while(keyNum<prevKeyNum){keyNum+=Note.allNoteCount}if(x==0){this.minUsedKeyNum=keyNum}elem=$('#note_num_'+keyNum);elem.addClass(note_class);if(x==0){elem.addClass(root_class)}prevKeyNum=keyNum}this.maxUsedKeyNum=prevKeyNum};KeyPositionPiano.setHiddenKeys=function(mobileOrTablet){var numKeysBreakpoint,x,elem;if(mobileOrTablet=='tablet'){numKeysBreakpoint=instrumentInfo.num_frets_tablet}else if(mobileOrTablet=='mobile'){numKeysBreakpoint=instrumentInfo.num_frets_mobile}else{console.log('invalid break point value');return}var firstKeyNum=Math.floor((instrumentInfo.num_frets_desktop-numKeysBreakpoint)/2);var lastKeyNum=firstKeyNum+numKeysBreakpoint-1;if(this.minUsedKeyNum>=0){while(this.maxUsedKeyNum>=lastKeyNum){firstKeyNum++;lastKeyNum++}while(this.minUsedKeyNum<=firstKeyNum){firstKeyNum--;lastKeyNum--}}for(x=0;x<this.numKeys;x++){elem=$('#note_num_'+x);if(x<firstKeyNum||x>lastKeyNum){elem.addClass('hide_'+mobileOrTablet)}else{elem.removeClass('hide_'+mobileOrTablet)}if(x==firstKeyNum){elem.addClass('is_first_'+mobileOrTablet)}else{elem.removeClass('is_first_'+mobileOrTablet)}if(x==lastKeyNum){elem.addClass('is_last_'+mobileOrTablet)}else{elem.removeClass('is_last_'+mobileOrTablet)}}};